using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<TicketModelTrainer>();

// Train model at startup and register the prediction engine pool
var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");

builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

// Train and save model before handling requests
using (var scope = app.Services.CreateScope())
{
    var trainer = scope.ServiceProvider.GetRequiredService<TicketModelTrainer>();
    var schema = trainer.GetDataSchema(dataPath);
    var model = trainer.TrainModel(dataPath, out var metrics);
    trainer.SaveModel(model, modelPath, schema);

    var logger = scope.ServiceProvider.GetRequiredService<ILogger<Program>>();
    logger.LogInformation("Evaluation Metrics:");
    logger.LogInformation("  MicroAccuracy:  {Micro:F4}", metrics.MicroAccuracy);
    logger.LogInformation("  MacroAccuracy:  {Macro:F4}", metrics.MacroAccuracy);
    logger.LogInformation("  LogLoss:        {LogLoss:F4}", metrics.LogLoss);
    logger.LogInformation("  LogLossReduction: {Reduction:F4}", metrics.LogLossReduction);
}

app.MapControllers();
app.Run();

